1	export type DesktopLayoutCounts = {
2	  stackedCount: number;
3	  gridCount: number;
4	  remainingCount: number;
5	  showButton: boolean;
6	};
7	
8	/**
9	 * Desktop item-count layout, per SFCC-731's Acceptance Criteria (confirmed 2026-09-04): 3 items
10	 * -> 3 stacked, no grid; 4 -> 2 stacked + 2-up grid; 5 -> 2 stacked + 2-up grid + "+1"; 6 -> 2
11	 * stacked + 4-up grid; 7+ -> 2 stacked + 4-up grid + "+X" (X = total - 6). The grid only ever
12	 * shows 2 or 4 items (never an uneven 3) — at 5 total, one of the 3 items left after stacking is
13	 * held back behind "+1" rather than shown as a lopsided 3-cell row.
14	 *
15	 * Below 3, this generalises the same "everything stacked, no grid" shape; the AC doesn't cover
16	 * 1-2 items explicitly, so the single-image case keeps this component's existing, tested
17	 * behaviour (no button — nothing to view more of), and 2 extends the button-shown pattern
18	 * confirmed at 3.
19	 */
20	export const getDesktopLayoutCounts = (total: number): DesktopLayoutCounts => {
21	  if (total <= 3) {
22	    return { stackedCount: total, gridCount: 0, remainingCount: 0, showButton: total >= 2 };
23	  }
24	  const available = total - 2;
25	  if (available <= 2) return { stackedCount: 2, gridCount: available, remainingCount: 0, showButton: true };
26	  if (available === 3) return { stackedCount: 2, gridCount: 2, remainingCount: 1, showButton: true };
27	  return { stackedCount: 2, gridCount: 4, remainingCount: available - 4, showButton: true };
28	};
29

1	import { describe, test, expect } from 'vitest';
2	import { getDesktopLayoutCounts } from './getDesktopLayoutCounts';
3	
4	describe('getDesktopLayoutCounts', () => {
5	  test('1 item — all stacked, no button (nothing to view more of)', () => {
6	    expect(getDesktopLayoutCounts(1)).toEqual({ stackedCount: 1, gridCount: 0, remainingCount: 0, showButton: false });
7	  });
8	
9	  test('2 items — all stacked, plain button', () => {
10	    expect(getDesktopLayoutCounts(2)).toEqual({ stackedCount: 2, gridCount: 0, remainingCount: 0, showButton: true });
11	  });
12	
13	  test('3 items — 3 stacked, no grid, plain button (AC 1)', () => {
14	    expect(getDesktopLayoutCounts(3)).toEqual({ stackedCount: 3, gridCount: 0, remainingCount: 0, showButton: true });
15	  });
16	
17	  test('4 items — 2 stacked + 2-up grid, plain button (AC 2)', () => {
18	    expect(getDesktopLayoutCounts(4)).toEqual({ stackedCount: 2, gridCount: 2, remainingCount: 0, showButton: true });
19	  });
20	
21	  test('5 items — 2 stacked + 2-up grid, "+1" (holds back 1 rather than a lopsided 3-cell row) (AC 3)', () => {
22	    expect(getDesktopLayoutCounts(5)).toEqual({ stackedCount: 2, gridCount: 2, remainingCount: 1, showButton: true });
23	  });
24	
25	  test('6 items — 2 stacked + 4-up grid, plain button (AC 4)', () => {
26	    expect(getDesktopLayoutCounts(6)).toEqual({ stackedCount: 2, gridCount: 4, remainingCount: 0, showButton: true });
27	  });
28	
29	  test('7 items — 2 stacked + 4-up grid, "+1" (AC 5, X = total - 6)', () => {
30	    expect(getDesktopLayoutCounts(7)).toEqual({ stackedCount: 2, gridCount: 4, remainingCount: 1, showButton: true });
31	  });
32	
33	  test('10 items — grid caps at 4, remainder keeps growing (AC 5 generalised)', () => {
34	    expect(getDesktopLayoutCounts(10)).toEqual({ stackedCount: 2, gridCount: 4, remainingCount: 4, showButton: true });
35	  });
36	});
