1	import React, { useEffect, useRef, useState } from 'react';
2	import {
3	  Image,
4	  Modal,
5	  ModalContent,
6	  ModalOverlay,
7	  VisuallyHidden,
8	  chakra,
9	  useMultiStyleConfig,
10	} from '@chakra-ui/react';
11	import { defineMessages, useIntl } from 'react-intl';
12	import { ZimmButton } from '../../atoms/zimmButton';
13	import { ZimmMediaTile } from '../../atoms/zimmMediaTile';
14	import type { ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
15	import { ZimmColourSwatchGroup } from '../../molecules/zimmColourSwatchGroup';
16	import type { ZimmColourSwatchValue } from '../../molecules/zimmColourSwatchGroup';
17	import { useZimmModal } from 'app/hooks/useZimmModal';
18	import { useUiCopy } from 'app/hooks/useUiCopy';
19	import { buildDisImageSrc, resolveDisImageSrc } from 'app/utils/buildDisImageSrc';
20	
21	const messages = defineMessages({
22	  close: { id: 'gallery_overlay.trigger.close', defaultMessage: 'Close gallery' },
23	  goToImage: { id: 'gallery_overlay.thumbnail.label', defaultMessage: 'Go to image {index} of {total}' },
24	  currentImage: { id: 'gallery_overlay.live.current', defaultMessage: '{alt}. Image {index} of {total}.' },
25	  imageStack: { id: 'gallery_overlay.body.label', defaultMessage: 'Product images' },
26	});
27	
28	const ZIMM_GALLERY_OVERLAY_RECIPE = 'ZimmGalleryOverlay';
29	
30	type ZimmGalleryOverlayProps = {
31	  /** Whether the overlay is open. Nothing renders until this and mount-gating (SSR safety) both
32	   *  clear — see useZimmModal. */
33	  isOpen: boolean;
34	  onClose: () => void;
35	  productName: string;
36	  /** Ordered photo/video sequence — the same shape/order ZimmProductGallery renders. */
37	  media: ZimmGalleryMediaItem[];
38	  /**
39	   * Offered colour values for "Also available in" — the same combined natural + related
40	   * (SFCC-708) set the main PDP sidebar shows. Undefined/single-item hides the row.
41	   */
42	  colourValues?: ZimmColourSwatchValue[];
43	  /** The currently selected colour's `value`, e.g. `colourAttr.selectedValue.value`. */
44	  selectedColourValue?: string;
45	  /**
46	   * SFCC-731 AC 19 — DIS quality (`q` param, 0-100) for every image's responsive request.
47	   * Forwarded to `ZimmMediaTile`/`buildDisImageSrc`. Defaults to that function's own default
48	   * (80) when omitted.
49	   */
50	  imageQuality?: number;
51	};
52	
53	// SFCC-731 AC 19 — matches `bodyInner`'s own BODY_MAX_WIDTH exactly (720px), the real column
54	// width these images render at from `lg` up; full-bleed below that.
55	const IMAGE_WIDTHS = { base: '100vw', lg: 720 };
56	
57	// Thumbnail strip — a single fixed size regardless of breakpoint (matches `thumbnail`'s own
58	// 102px width, zimmGalleryOverlay.css.ts), so this needs a resolved request width rather than
59	// the full responsive `<picture>` machinery. 2x for standard retina density.
60	const THUMBNAIL_REQUEST_WIDTH = 204;
61	// Rendered (CSS) size, for the <img> width/height attributes — half of the 2x request width
62	// above, matching `thumbnail`'s own 102px/3:4 aspect ratio (zimmGalleryOverlay.css.ts).
63	const THUMBNAIL_DISPLAY_WIDTH = 102;
64	const THUMBNAIL_DISPLAY_HEIGHT = 136;
65	
66	/**
67	 * Organism — the SFCC-731 "expanded state" full-screen gallery overlay (AC 12-25). Built
68	 * directly on Chakra's Modal/ModalOverlay/ModalContent (not the ZimmModal atom — that atom's
69	 * chrome is a fixed-maxWidth centered card, a different contract than this full-viewport
70	 * takeover) plus the existing useZimmModal() hook for SSR-safe mount gating. Focus trap, initial
71	 * focus, focus restore to the trigger, body-scroll lock (which also satisfies AC 13's "return to
72	 * the same scroll position" — locking/unlocking overflow never moves window.scrollY), and
73	 * Escape/overlay-click-to-close all come from Chakra rather than being hand-rolled, the same
74	 * reasoning ZimmModal itself documents.
75	 *
76	 * Only true desktop (`lg`, 992px, and up — the same breakpoint ZimmProductGallery itself uses)
77	 * renders the 3-column sticky header (name + colour selector | thumbnail jump-strip | close)
78	 * above a centred, max-width image column. Tablet follows the mobile layout instead (design team
79	 * direction, 2026-09-05): name + close on one row, colour selector below, no thumbnail strip,
80	 * full-width image column — matches Figma nodes 40001999:5982 (desktop) and 40001999:5751
