188	
189	  const closeButton = (
190	    <ZimmButton
191	      variant="icon"
192	      icon="close"
193	      label={intl.formatMessage(messages.close)}
194	      onClick={onClose}
195	      sx={styles.closeButton}
196	    />
197	  );
198	
199	  const nameText = (
200	    <chakra.p aria-hidden textStyle="productNames" color="var(--zimm-color-text-default)">
201	      {productName}
202	    </chakra.p>
203	  );
204	
205	  // AC 15 — circle swatches, shown at every viewport whenever the product has at least one
206	  // offered colour. Reuses ZimmColourSwatchGroup directly (variant="circle") — the same molecule
207	  // the main PDP sidebar uses, so related-colour (SFCC-708) forceReload navigation, keyboard nav,
208	  // and pagination all come for free instead of being reimplemented here. The group itself
