214	  // several are alternatives ("Also available in"), so the two labels intentionally diverge.
215	  const offeredColourCount = (colourValues ?? []).filter((v) => Boolean(v.imageUrl) && v.orderable !== false).length;
216	  const colourSwatchesSection = colourValues && offeredColourCount > 0 && (
217	    <chakra.div __css={styles.colourSwatches}>
218	      <ZimmColourSwatchGroup
219	        values={colourValues}
220	        selectedValue={selectedColourValue}
221	        variant="circle"
222	        {...(offeredColourCount > 1
223	          ? { label: t('pdp.gallery_overlay.colourLabel', 'Also available in'), appendColon: false }
224	          : {})}
225	      />
226	    </chakra.div>
227	  );
