246	              loading="lazy"
247	              htmlWidth={THUMBNAIL_DISPLAY_WIDTH}
248	              htmlHeight={THUMBNAIL_DISPLAY_HEIGHT}
249	              objectFit="cover"
250	              __css={styles.thumbnailImage}
251	            />
252	          </chakra.button>
253	        );
254	      })}
255	    </chakra.div>
256	  );
257	
258	  return (
259	    // size="full" — Chakra's own built-in full-viewport dialog size (clears the default `md`
260	    // max-width and centering margin at the source, via the same theme-resolution path Chakra
