19	/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
20	export type ZimmColourSwatchValue = {
21	  value: string;
22	  name: string;
23	  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
24	  imageUrl?: string;
25	  /** Router destination URL for this colour. Absent on the quick-view modal path. */
26	  href?: string;
27	  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
28	  orderable?: boolean;
29	  /**
30	   * When true, clicking navigates via a native anchor (full page reload) rather than a router
31	   * Link. Set for related-colour swatches (SFCC-708) that link to a different master product.
32	   */
33	  forceReload?: boolean;
34	};
