224	            return (
225	              // All swatches are always in the DOM so screen readers can navigate the full set
226	              // and aria-posinset/aria-setsize reports the correct total count ("N of M" where
227	              // M = all offered colours, not just the current page). Off-page swatches are
228	              // absolutely positioned — removed from the flex flow so they don't widen the row —
229	              // and clip-path'd to a 0×0 visible area so they are invisible on screen while
230	              // remaining in the accessibility tree.
231	              <chakra.span
232	                key={v.value}
233	                data-swatch-value={v.value}
234	                style={isOnPage ? undefined : { position: 'absolute', clipPath: 'inset(50%)' }}
235	              >
236	                <ZimmColourSwatch
237	                  name={v.name}
238	                  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
239	                  imageUrl={v.imageUrl!}
240	                  href={v.href}
241	                  forceReload={v.forceReload}
242	                  onClick={onSelect ? () => onSelect(v.value) : undefined}
243	                  isSelected={v.value === selectedValue}
244	                  isFocusable={isFocusable}
245	                  posInSet={i + 1}
246	                  setSize={offered.length}
247	                  variant={variant}
248	                />
249	              </chakra.span>
250	            );
251	          })}
252	        </chakra.div>
253	      )}
254	    </chakra.div>
255	  );
256	};
257	
258	export default ZimmColourSwatchGroup;
